29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
40	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Minimal syntactic check for an email address: a non-empty local part, a single
66	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final TelephoneNormalizer telephoneNormalizer;
79	
80	    private final AddressNormalizer addressNormalizer;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper,
86	                                 TelephoneNormalizer telephoneNormalizer,
87	                                 AddressNormalizer addressNormalizer) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	        this.telephoneNormalizer = telephoneNormalizer;
93	        this.addressNormalizer = addressNormalizer;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        if (owner.getRegistrationDate() == null) {
127	            owner.setRegistrationDate(LocalDate.now());
128	        }
129	        String address = addressNormalizer.normalize(owner.getAddress());
130	        if (address.isBlank()) {
131	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
132	        }
133	        owner.setAddress(address);
134	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
135	        if (telephone == null) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        owner.setTelephone(telephone);
139	        String email = owner.getEmail();
140	        if (email != null) {
141	            email = email.trim();
142	            if (!EMAIL_PATTERN.matcher(email).matches()) {
143	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
144	            }
145	            owner.setEmail(email.toLowerCase(Locale.ROOT));
146	        }
147	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
148	            .map(Owner::getTelephone)
149	            .filter(Objects::nonNull)
150	            .map(telephoneNormalizer::normalize)
151	            .anyMatch(telephone::equals);
152	        if (telephoneInUse) {
153	            return new ResponseEntity<>(HttpStatus.CONFLICT);
154	        }
155	        String lastNameKey = normalizeIdentity(owner.getLastName());
156	        String addressKey = addressNormalizer.normalize(owner.getAddress());
157	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
158	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
159	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
160	                    && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
161	            if (householdDuplicate) {
162	                return new ResponseEntity<>(HttpStatus.CONFLICT);
163	            }
164	        }
165	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
166	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
167	        this.clinicService.saveOwner(owner);
168	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
169	        headers.setLocation(UriComponentsBuilder.newInstance()
170	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
171	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    /**
175	     * Normalize a value for household-identity comparison: null becomes an empty
176	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
177	     * to a single space, and the result is lower-cased.
178	     */
179	    private static String normalizeIdentity(String value) {
180	        if (value == null) {
181	            return "";
182	        }
183	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
184	    }
185	
186	    /**
187	     * Build the stable, shared household identifier for an owner, formatted
188	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
189	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
190	     * Owners in the same household (same normalized lastName and address) therefore
191	     * derive an identical householdId.
192	     */
193	    private static String householdId(String lastNameKey, String addressKey) {
194	        String source = lastNameKey + "|" + addressKey;
195	        try {
196	            byte[] digest = MessageDigest.getInstance("SHA-256")
197	                .digest(source.getBytes(StandardCharsets.UTF_8));
198	            StringBuilder sb = new StringBuilder(digest.length * 2);
199	            for (byte b : digest) {
200	                sb.append(String.format("%02x", b));
201	            }
202	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
203	        }
204	        catch (NoSuchAlgorithmException e) {
205	            throw new IllegalStateException("SHA-256 not available", e);
206	        }
207	    }
208	
209	    /**
210	     * Build the customer code assigned on create, formatted {@code '<LAST3>-<NNNN>'}:
211	     * LAST3 is the upper-cased first three letters of {@code lastName} and NNNN is a
212	     * global 4-digit zero-padded sequence equal to one more than the current number of
213	     * owners (e.g. 'SMI-0007').
214	     */
215	    private String nextCustomerCode(String lastName) {
216	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
217	        int sequence = this.clinicService.findAllOwners().size() + 1;
218	        return String.format("%s-%04d", last3, sequence);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
224	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
225	        if (currentOwner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        currentOwner.setAddress(ownerFieldsDto.getAddress());
229	        currentOwner.setCity(ownerFieldsDto.getCity());
230	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
231	        currentOwner.setLastName(ownerFieldsDto.getLastName());
232	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
233	        this.clinicService.saveOwner(currentOwner);
234	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Transactional
239	    @Override
240	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
241	        Owner owner = this.clinicService.findOwnerById(ownerId);
242	        if (owner == null) {
243	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	        }
245	        this.clinicService.deleteOwner(owner);
246	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
247	    }
248	
249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
252	        Owner owner = this.clinicService.findOwnerById(ownerId);
253	        if (owner == null) {
254	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	        }
256	        HttpHeaders headers = new HttpHeaders();
257	        Pet pet = petMapper.toPet(petFieldsDto);
258	        owner.setId(ownerId);
259	        pet.setOwner(owner);
260	        pet.getType().setName(null);
261	        this.clinicService.savePet(pet);
262	        PetDto petDto = petMapper.toPetDto(pet);
263	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
264	            .buildAndExpand(pet.getId()).toUri());
265	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
271	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
272	        if (currentOwner != null) {
273	            Pet currentPet = this.clinicService.findPetById(petId);
274	            if (currentPet != null) {
275	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
276	                currentPet.setName(petFieldsDto.getName());
277	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
278	                this.clinicService.savePet(currentPet);
279	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
280	            }
281	        }
282	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	    }
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
288	        HttpHeaders headers = new HttpHeaders();
289	        Visit visit = visitMapper.toVisit(visitFieldsDto);
290	        Pet pet = new Pet();
291	        pet.setId(petId);
292	        visit.setPet(pet);
293	        this.clinicService.saveVisit(visit);
294	        VisitDto visitDto = visitMapper.toVisitDto(visit);
295	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
296	            .buildAndExpand(visit.getId()).toUri());
297	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
298	    }
299	
300	
301	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
302	    @Override
303	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
304	        Owner owner = this.clinicService.findOwnerById(ownerId);
305	        if (owner != null) {
306	            Pet pet = owner.getPet(petId);
307	            if (pet != null) {
308	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
309	            }
310	        }
311	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
312	    }
313	}
