1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    OwnerDto toOwnerDto(Owner owner);
25	
26	    /**
27	     * The upper-cased first letters of firstName and lastName, dot-separated with a
28	     * trailing dot, e.g. 'J.S.'.
29	     */
30	    default String initials(Owner owner) {
31	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
32	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
33	    }
34	
35	    Owner toOwner(OwnerDto ownerDto);
36	
37	    @Mapping(target = "id", ignore = true)
38	    @Mapping(target = "pets", ignore = true)
39	    Owner toOwner(OwnerFieldsDto ownerDto);
40	
41	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
42	
43	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
44	
45	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
46	        OwnerPageDto ownerPageDto = new OwnerPageDto();
47	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
48	        ownerPageDto.setPage(ownerPage.getNumber());
49	        ownerPageDto.setSize(ownerPage.getSize());
50	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
51	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
52	        return ownerPageDto;
53	    }
54	}
